function jgParse(s){ return JSON.parse(s); }
function jgGraph(obj, rootId){
  var nodes=[], edges=[], idc=0;
  function walk(o, parent, key, depth){
    var id='n'+(idc++);
    var label = key!==null ? key : (rootId||'root');
    var type = Array.isArray(o)?'array': o&&typeof o==='object'?'object':'value';
    var val = type==='value' ? String(o) : (type==='array'?('['+o.length+']'):'{'+(Object.keys(o).length)+'}');
    nodes.push({id:id, label:label, type:type, val:val, depth:depth});
    if(parent) edges.push({from:parent, to:id});
    if(type==='object'){ var ks=Object.keys(o); for(var i=0;i<ks.length;i++) walk(o[ks[i]], id, ks[i], depth+1); }
    else if(type==='array'){ for(var i=0;i<o.length;i++) walk(o[i], id, '['+i+']', depth+1); }
    return id;
  }
  walk(obj, null, null, 0);
  return {nodes:nodes, edges:edges};
}
function jgLayout(graph, W, H){
  var byDepth={}, maxDepth=0;
  graph.nodes.forEach(function(n){ (byDepth[n.depth]=byDepth[n.depth]||[]).push(n); maxDepth=Math.max(maxDepth,n.depth); });
  var colW=(W-40)/(maxDepth+1), rowH=34;
  graph.nodes.forEach(function(n){ n.x=n.depth*colW+30; });
  Object.keys(byDepth).forEach(function(d){ var arr=byDepth[d]; arr.forEach(function(n,i){ n.y=20+i*rowH+10; }); });
  graph._h = 20 + (Math.max.apply(null, Object.keys(byDepth).map(function(d){ return byDepth[d].length; })))*rowH + 10;
  return graph;
}
function jgSvg(graph, W, H){
  graph=jgLayout(graph, W, H);
  var pos={}; graph.nodes.forEach(function(n){ pos[n.id]={x:n.x,y:n.y}; });
