  graph.edges.forEach(function(e){ var a=pos[e.from], b=pos[e.to]; s+='<path d="M'+(a.x+8)+' '+a.y+' C'+(a.x+60)+' '+a.y+' '+(b.x-60)+' '+b.y+' '+b.x+'" fill="none" stroke="#3f3f46" stroke-width="1.2"/>'; });
  graph.nodes.forEach(function(n){ var col=n.type==='object'?'#5E6AD2':n.type==='array'?'#22D3EE':'#10B981'; s+='<g transform="translate('+n.x+','+n.y+')"><rect x="0" y="-12" width="120" height="24" rx="6" fill="#141417" stroke="'+col+'" stroke-width="1.3"/>'; s+='<text x="8" y="4" fill="#E4E4E7" font-size="11">'+esc(n.label)+' <tspan fill="#71717A">'+(n.val.length>10?n.val.slice(0,9)+'…':esc(n.val))+'</tspan></text></g>'; });
  return s+'</svg>';
}
function esc(s){ return String(s).replace(/[&<>]/g,function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c]; }); }
